{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated_intermediate as select Null as customer_id ,upper(STORE_NAME) as SHOP_NAME ,upper(STORE_NAME) AS marketplace ,upper(channel) AS CHANNEL ,upper(channel) AS SOURCE ,ORDER_ID ,ORDER_ID reference_code ,TELEPHONE as PHONE ,concat(CUSTOMER_FIRSTNAME,\' \',CUSTOMER_LASTNAME) as NAME ,CUSTOMER_EMAIL as EMAIL ,updated_at AS SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,upper(PRODUCT_NAME) AS PRODUCT_NAME ,STORE_CURRENCY_CODE CURRENCY ,upper(CITY) City ,upper(REGION) AS State ,upper(STATUS) as Order_Status ,CREATED_AT::date AS Order_Date ,CREATED_AT Order_TimeStamp ,QTY_ORDERED AS QUANTITY ,ifnull(PRICE_INCL_TAX,0) AS GROSS_SALES_BEFORE_TAX ,0 AS DISCOUNT ,ifnull(PRICE_INCL_TAX,0) - ifnull(BASE_PRICE,0) TAX ,0 as SHIPPING_PRICE ,ifnull(BASE_PRICE,0) AS SELLING_PRICE ,upper(STATUS) as OMS_Order_Status ,upper(STATUS) AS SHIPPING_STATUS ,upper(STATUS) FINAL_SHIPPING_STATUS ,ITEM_ID as SALEORDERITEMCODE ,ITEM_ID as SALES_ORDER_ITEM_ID ,NULL AWB ,NULL Payment_Gateway ,PAYMENT_METHOD Payment_Mode ,NULL COURIER ,NULL as DISPATCH_DATE ,UPDATED_AT DELIVERED_DATE ,case when lower(STATUS) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,case when CREDITMEMO_NUMBER is null then 0 else 1 end AS RETURN_FLAG ,SCM_QTY_REFUNDED returned_quantity ,null as returned_sales ,ifnull(QTY_CANCELED,0) cancelled_quantity ,NULL as NEW_CUSTOMER_FLAG ,NULL as ACQUISITION_PRODUCT ,NULL AS DAYS_IN_SHIPMENT ,NULL AS ACQUSITION_DATE ,SKU as SKU_CODE ,upper(PRODUCT_NAME) as PRODUCT_NAME_FINAL ,NULL as PRODUCT_CATEGORY ,NULL CATEGORY ,NULL WAREHOUSE ,POSTCODE pincode ,(COALESCE(UPDATED_PRICE, 0) * COALESCE(QTY_INVOICED, 0))- ( COALESCE(TRY_TO_NUMBER(NULLIF(TRIM(REFUND_ROW_TOTAL), \'\')), 0)) +(ifnull(SHIPPING_AMOUNT,0))as sales_exc_vat ,(COALESCE(UPDATED_PRICE, 0) * COALESCE(QTY_ORDERED, 0)) - ( COALESCE(TRY_TO_NUMBER(NULLIF(TRIM(REFUND_ROW_TOTAL), \'\')), 0))+(ifnull(SHIPPING_AMOUNT,0)) as orders_ex_vat ,(COALESCE(UPDATED_PRICE, 0) * COALESCE(QTY_ORDERED, 0)) as PRODUCT_ORDERS_EXC_VAT ,(COALESCE(UPDATED_PRICE, 0) * COALESCE(QTY_INVOICED, 0)) as PRODUCT_SALES_EXC_VAT from zeproc_db.maplemonk.Zeproc_db_Magento_Sales_Fact_items ; create or replace table Zeproc_db.MAPLEMONK.Final_customerID as with new_phone_numbers as ( select phone, contact_num, 19700000000 + row_number() over( order by contact_num asc ) as maple_monk_id from ( select distinct right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'),10) as contact_num, phone from Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated_intermediate ) a ), int as ( select contact_num, email, coalesce(maple_monk_id,id2) as maple_monk_id from ( select contact_num, email, maple_monk_id, 19800000000+row_number() over(partition by maple_monk_id is NULL order by email asc ) as id2 from ( select distinct coalesce(p.contact_num,right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10)) as contact_num, e.email, maple_monk_id from ( select phone as contact_num, email from Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated_intermediate ) e left join new_phone_numbers p on p.contact_num = right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10) ) a ) b ) select contact_num, email, maple_monk_id from int where coalesce(contact_num,email) is not NULL; create or replace table Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated as select coalesce(m.maple_monk_id_phone, d.maple_monk_id) as customer_id_final, min(order_date) over(partition by customer_id_final) as acquisition_date, min(case when lower(order_status) not in (\'cancelled\') then order_date end) over(partition by customer_id_final) as first_complete_order_date, m.* from ( select c.maple_monk_id as maple_monk_id_phone, o.* from Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated_intermediate o left join ( select * from ( select contact_num phone, maple_monk_id, row_number() over (partition by contact_num order by maple_monk_id asc) magic from Zeproc_db.MAPLEMONK.Final_customerID ) where magic =1 )c on c.phone = right(regexp_replace(o.phone, \'[^a-zA-Z0-9]+\'),10) )m left join ( select distinct maple_monk_id, email from Zeproc_db.MAPLEMONK.Final_customerID where contact_num is null )d on d.email = m.email; ALTER TABLE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated drop COLUMN new_customer_flag ; ALTER TABLE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated ADD COLUMN new_customer_flag varchar(50); ALTER TABLE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated ADD COLUMN new_customer_flag_month varchar(50); ALTER TABLE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated drop COLUMN acquisition_product ; ALTER TABLE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated ADD COLUMN acquisition_product varchar(16777216); ALTER TABLE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated ADD COLUMN acquisition_channel varchar(16777216); ALTER TABLE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated ADD COLUMN acquisition_marketplace varchar(16777216); UPDATE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date then \'New\' WHEN Order_Date < first_complete_order_date or first_complete_order_date is null THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date then \'Repeat\' END AS Flag FROM Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) in (\'cancelled\') end) THEN \'Yet to make completed order\' ELSE new_customer_flag END; UPDATE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Last_day(order_date, \'month\') = Last_day(first_complete_order_date, \'month\') THEN \'New\' WHEN Last_day(order_date, \'month\') < Last_day(first_complete_order_date, \'month\') or acquisition_date is null THEN \'Yet to make completed order\' WHEN Last_day(order_date, \'month\') > Last_day(first_complete_order_date, \'month\') THEN \'Repeat\' END AS Flag FROM Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' ELSE new_customer_flag_month END; CREATE OR replace temporary TABLE Zeproc_db.MAPLEMONK.temp_source_1 AS SELECT DISTINCT customer_id_final, channel, marketplace FROM ( SELECT DISTINCT customer_id_final, order_date, source as channel, shop_name as marketplace, Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate FROM Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated ) res WHERE order_date=firstorderdate; UPDATE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated AS a SET a.acquisition_channel=b.channel FROM Zeproc_db.MAPLEMONK.temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; UPDATE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated AS a SET a.acquisition_marketplace=b.marketplace FROM Zeproc_db.MAPLEMONK.temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE Zeproc_db.MAPLEMONK.temp_product_1 AS SELECT DISTINCT customer_id_final, product_name_final, Row_number() OVER (partition BY customer_id_final ORDER BY SELLING_PRICE DESC) rowid FROM ( SELECT DISTINCT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate FROM Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated )res WHERE order_date=firstorderdate; UPDATE Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated AS A SET A.acquisition_product=B.product_name_final FROM ( SELECT * FROM Zeproc_db.MAPLEMONK.temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; CREATE table if not exists Zeproc_db.MAPLEMONK.Zeproc_db_easyecom_returns_intermediate (ORDER_ID NUMBER,INVOICE_ID NUMBER,SUBORDER_ID VARIANT,REFERENCE_CODE VARCHAR,CREDIT_NOTE_ID NUMBER,ORDER_DATE TIMESTAMP_NTZ,INVOICE_DATE TIMESTAMP_NTZ,RETURN_DATE TIMESTAMP_NTZ,MANIFEST_DATE TIMESTAMP_NTZ,IMPORT_DATE TIMESTAMP_NTZ,LAST_UPDATE_DATE TIMESTAMP_NTZ,COMPANY_PRODUCT_ID VARIANT,PRODUCTNAME VARCHAR,PRODUCT_ID VARIANT,SKU VARCHAR,MARKETPLACE VARCHAR,MARKETPLACE_ID NUMBER,REPLACEMENT_ORDER NUMBER,RETURN_REASON VARCHAR,RETURNED_QUANTITY FLOAT,RETURN_AMOUNT_WITHOUT_TAX FLOAT,RETURN_TAX FLOAT,RETURN_SHIPPING_CHARGE FLOAT,RETURN_MISC FLOAT,TOTAL_RETURN_AMOUNT FLOAT) ; Create or replace table Zeproc_db.MAPLEMONK.Zeproc_db_easyecom_returns_fact_items as select ifnull(FE.Source,\'NA\') Marketing_CHANNEL ,FR.* from Zeproc_db.MAPLEMONK.Zeproc_db_easyecom_returns_intermediate FR left join (select distinct replace(reference_code,\'#\',\'\') REFERENCE_CODE, Source from Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated) FE on FR.REFERENCE_CODE = FE.REFERENCE_CODE; CREATE table if not exists Zeproc_db.MAPLEMONK.Zeproc_db_UNICOMMERCE_RETURNS_INTERMEDIATE ( MARKETPLACE VARCHAR ,SOURCE VARCHAR ,ORDER_ID VARCHAR ,REFERENCE_CODE VARCHAR ,PHONE VARCHAR ,NAME VARCHAR ,EMAIL VARCHAR ,ORDER_DATE TIMESTAMP_NTZ ,RETURN_DISPLAYCODE VARCHAR ,RETURN_STATUS VARCHAR ,INVENTORY_RECEIVED_DATE TIMESTAMP_NTZ ,RETURN_COMPLETE_DATE TIMESTAMP_NTZ ,RETURN_INVOICE_DISPLAY_CODE VARCHAR ,RETURN_COURIER VARCHAR ,RETURN_PROVIDER_SHIPPING_STATUS VARCHAR ,RETURN_TRACKING_NUMBER VARCHAR ,RETURN_TYPE VARCHAR ,SALEORDERITEMCODE VARCHAR ,ITEMSKU VARCHAR ,ITEM_NAME VARCHAR ,INVENTORY_TYPE VARCHAR ); create or replace table Zeproc_db.MAPLEMONK.Zeproc_db_unicommerce_returns_fact_items as select ifnull(FE.channel,\'NA\') Marketing_CHANNEL ,FE.quantity RETURNED_QUANTITY ,FE.selling_price as TOTAL_RETURN_AMOUNT ,FE.tax as RETURN_TAX ,FE.selling_price - FE.tax as RETURN_AMOUNT_WITHOUT_TAX ,FR.* from Zeproc_db.MAPLEMONK.Zeproc_db_UNICOMMERCE_RETURNS_INTERMEDIATE FR left join (select replace(reference_code,\'#\',\'\') REFERENCE_CODE, SALEORDERITEMCODE, channel, Source, sum(quantity) quantity, sum(selling_price) Selling_price, sum(tax) tax from Zeproc_db.MAPLEMONK.Zeproc_db_sales_consolidated group by 1,2,3,4) FE on FR.REFERENCE_CODE = FE.REFERENCE_CODE and FR.saleOrderItemCode = FE.SALEORDERITEMCODE; create or replace table Zeproc_db.MAPLEMONK.Zeproc_db_RETURNS_CONSOLIDATED as select upper(MARKETPLACE) Marketplace ,Return_Date ,upper(Marketing_CHANNEL) Marketing_channel ,sum(RETURNED_QUANTITY) TOTAL_RETURNED_QUANTITY ,sum(TOTAL_RETURN_AMOUNT) TOTAL_RETURN_AMOUNT ,sum(RETURN_TAX) TOTAL_RETURN_TAX ,sum(RETURN_AMOUNT_WITHOUT_TAX) TOTAL_RETURN_AMOUNT_EXCL_TAX from Zeproc_db.MAPLEMONK.Zeproc_db_easyecom_returns_fact_items group by 1,2,3 union all select upper(MARKETPLACE) Marketplace ,RETURN_COMPLETE_DATE RETURN_DATE ,upper(Marketing_CHANNEL) Marketing_channel ,sum(RETURNED_QUANTITY) TOTAL_RETURNED_QUANTITY ,sum(TOTAL_RETURN_AMOUNT) TOTAL_RETURN_AMOUNT ,sum(RETURN_TAX) TOTAL_RETURN_TAX ,sum(RETURN_AMOUNT_WITHOUT_TAX) TOTAL_RETURN_AMOUNT_EXCL_TAX from Zeproc_db.MAPLEMONK.Zeproc_db_UNICOMMERCE_RETURNS_FACT_ITEMS group by 1,2,3;",
                    "transaction": true
